#include <print>
#include <vector>

int main() {
    int n = 100;                                   // 任务 1：把 50 改成 100
    std::vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i <= n; ++i) {
        if (!is_prime[i]) continue;
        for (int k = i * i; k <= n; k += i)
            is_prime[k] = false;
    }

    int total = 0;
    for (int i = 2; i <= n; ++i) {
        if (!is_prime[i]) continue;
        ++total;
        if (total == 10) { std::println("第 10 个是 {}", i); break; }
        std::print("{} ", i);
    }
    std::println("\n共 {} 个", total);
    return 0;
}

