#include <print>

bool trial(int x) {
    if (x < 2) return false;
    for (int d = 2; d * d <= x; ++d)
        if (x % d == 0) return false;
    return true;
}

int main() {
    int n = 100;
    int total = 0;
    for (int x = 2; x <= n; ++x) if (trial(x)) ++total;
    std::println("试除法：{} 个", total);
    return 0;
}
